23	    @Mapping(target = "householdId", expression = "java(java.util.UUID.nameUUIDFromBytes((owner.getLastName() + \"|\" + owner.getAddress()).trim().replaceAll(\"\\\\s+\", \" \").toLowerCase(java.util.Locale.ROOT).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString())")
24	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
25	    @Mapping(target = "membershipTier", expression = "java(Integer.valueOf(0).equals(owner.getNamesakeCount()) && owner.getEmail() != null && !owner.getEmail().isBlank() ? \"SILVER\" : \"BRONZE\")")
26	    @Mapping(target = "locality", expression = "java(java.util.Map.of(\"Sydney\", \"NSW\", \"Melbourne\", \"VIC\", \"Brisbane\", \"QLD\").getOrDefault(owner.getCity(), \"UNKNOWN\"))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    Owner toOwner(OwnerDto ownerDto);
30	
31	    @Mapping(target = "id", ignore = true)
32	    @Mapping(target = "pets", ignore = true)
33	    Owner toOwner(OwnerFieldsDto ownerDto);
34	
35	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
36	
37	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
38	
39	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
40	        OwnerPageDto ownerPageDto = new OwnerPageDto();
41	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
42	        ownerPageDto.setPage(ownerPage.getNumber());
43	        ownerPageDto.setSize(ownerPage.getSize());
44	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
45	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
46	        return ownerPageDto;
47	    }
