30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.http.converter.HttpMessageConverter;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.service.ClinicService;
36	import org.springframework.util.StreamUtils;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdviceAdapter;
41	
42	import tools.jackson.databind.JsonNode;
43	import tools.jackson.databind.ObjectMapper;
44	
45	/**
46	 * Rejects creating an owner whose lastName and address already belong to another owner
47	 * (compared case-insensitively with collapsed whitespace), answering 409 — unless the
48	 * request opts in with {@code sharesHousehold=true}. The opt-in flag is not a stored
49	 * owner field, so the raw body is read here before deserialization. Kept as its own
50	 * advice so the rule stays a small, self-contained unit.
51	 */
52	@ControllerAdvice
53	@Order(Ordered.HIGHEST_PRECEDENCE)
54	public class OwnerUniqueHouseholdAdvice extends RequestBodyAdviceAdapter {
55	
56	    private final ClinicService clinicService;
57	
58	    private final ObjectMapper objectMapper;
59	
60	    public OwnerUniqueHouseholdAdvice(ClinicService clinicService, ObjectMapper objectMapper) {
61	        this.clinicService = clinicService;
62	        this.objectMapper = objectMapper;
63	    }
64	
65	    @Override
66	    public boolean supports(MethodParameter methodParameter, Type targetType,
67	                            Class<? extends HttpMessageConverter<?>> converterType) {
68	        Method method = methodParameter.getMethod();
69	        return OwnerFieldsDto.class.equals(targetType)
70	            && method != null && "addOwner".equals(method.getName());
71	    }
72	
73	    @Override
74	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
75	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType)
76	            throws java.io.IOException {
77	        byte[] body = StreamUtils.copyToByteArray(inputMessage.getBody());
78	        JsonNode json = objectMapper.readTree(body);
79	        if (!json.path("sharesHousehold").asBoolean(false) && isDuplicateHousehold(json)) {
80	            throw new DuplicateHouseholdException();
81	        }
82	        return buffered(body, inputMessage.getHeaders());
83	    }
84	
85	    private boolean isDuplicateHousehold(JsonNode json) {
86	        String lastName = normalize(json.path("lastName").asString());
87	        String address = OwnerAddressNormalizationAdvice.normalize(json.path("address").asString());
88	        return clinicService.findAllOwners().stream()
89	            .anyMatch(o -> lastName.equals(normalize(o.getLastName()))
90	                && address.equals(OwnerAddressNormalizationAdvice.normalize(o.getAddress())));
91	    }
92	
93	    private static String normalize(String value) {
94	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
95	    }
96	
97	    private static HttpInputMessage buffered(byte[] body, HttpHeaders headers) {
98	        return new HttpInputMessage() {
99	            @Override
100	            public InputStream getBody() {
101	                return new ByteArrayInputStream(body);
102	            }
103	
104	            @Override
105	            public HttpHeaders getHeaders() {
106	                return headers;
107	            }
108	        };
109	    }
110	
111	    @ExceptionHandler(DuplicateHouseholdException.class)
112	    @ResponseBody
113	    public ResponseEntity<String> handleDuplicateHousehold(DuplicateHouseholdException e) {
114	        return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());
115	    }
116	
117	    /** Signals a lastName + address pair already used by another owner. */
118	    static class DuplicateHouseholdException extends RuntimeException {
119	
120	        DuplicateHouseholdException() {
121	            super("owner with the same last name and address already exists");
122	        }
123	    }
124	}
