31	
32	/**
33	 * Normalizes an owner's address before the request reaches the controller: whitespace is
34	 * trimmed and collapsed, the text is upper-cased and common street-type abbreviations are
35	 * expanded (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE). The normalized form is what gets
36	 * stored and returned, and (via {@link #normalize}) what address comparisons use. A blank
37	 * result is left for {@link OwnerFieldsValidationAdvice} to reject as a missing field. Kept
38	 * as its own advice so this rule stays a small, self-contained unit.
39	 */
40	@ControllerAdvice
41	@Order(Ordered.HIGHEST_PRECEDENCE)
42	public class OwnerAddressNormalizationAdvice extends RequestBodyAdviceAdapter {
43	
44	    private static final Map<String, String> ABBREVIATIONS =
45	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
46	
47	    @Override
48	    public boolean supports(MethodParameter methodParameter, Type targetType,
49	                            Class<? extends HttpMessageConverter<?>> converterType) {
50	        return OwnerFieldsDto.class.equals(targetType);
51	    }
52	
53	    @Override
54	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
55	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
56	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
57	        owner.setAddress(normalize(owner.getAddress()));
58	        return body;
59	    }
60	
61	    /** Canonical address form: trimmed, whitespace-collapsed, upper-cased, abbreviations expanded. */
62	    static String normalize(String address) {
63	        if (address == null) {
64	            return "";
